import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File

class CartTest {
    @Test
    fun enforcesCurrentLimit() {
        val limit = File("max_items.txt").readText().trim().toInt()
        assertTrue(Cart.canAdd(limit))
        assertFalse(Cart.canAdd(limit + 1))
    }
